function resolveApiFor(override) {
        const o = override || {};
        if (o.preset && cfg.apiPresets && cfg.apiPresets[o.preset]) {
            const pr = cfg.apiPresets[o.preset];
            return { apiType: pr.apiType || 'custom', url: String(pr.apiUrl || '').trim().replace(/\/+$/, ''), key: String(pr.apiKey || '').trim(), model: String(pr.model || '').trim(), proxyPreset: String(pr.proxyPreset || '').trim() };
        }
        const apiType = o.apiType !== undefined ? o.apiType : cfg.apiType;
        const proxyPreset = o.proxyPreset !== undefined ? o.proxyPreset : cfg.proxyPreset;
        if (apiType === 'preset' && proxyPreset) {
            const preset = getFn('getPreset');
            if (preset) {
                try { const p = preset(proxyPreset); const s = p?.settings || {}; if (s.apiurl) return { apiType: 'preset', url: String(s.apiurl).trim().replace(/\/+$/, ''), key: String(s.key || '').trim(), model: o.model || cfg.model || String(s.model || '').trim(), proxyPreset }; } catch (e) { }
            }
        }
        return { apiType, url: String(o.apiUrl !== undefined ? o.apiUrl : cfg.apiUrl).trim().replace(/\/+$/, ''), key: String(o.apiKey !== undefined ? o.apiKey : cfg.apiKey).trim(), model: String(o.model !== undefined ? o.model : cfg.model).trim(), proxyPreset };
    }

