async function testApi(override, kind) {
        const api = resolveApiFor(override);
        if (!api.url) throw new Error('未配置 API 地址');
        if (kind === 'embedding') {
            if (!api.model) throw new Error('未配置 Embedding 模型');
            const endpoint = /\/embeddings$/i.test(api.url) ? api.url : `${api.url}/embeddings`;
            const headers = { 'Content-Type': 'application/json' };
            if (api.key) headers['Authorization'] = `Bearer ${api.key}`;
            const t0 = Date.now();
            const res = await D.fetch(endpoint, { method: 'POST', headers, body: JSON.stringify({ model: api.model, input: ['测试'] }) });
            if (!res.ok) { const t = await res.text().catch(() => res.statusText); throw new Error(`HTTP ${res.status}: ${t.slice(0, 200)}`); }
            return { ok: true, ms: Date.now() - t0, kind };
        }
        if (kind === 'rerank') {
            if (!api.model) throw new Error('未配置 Rerank 模型');
            const endpoint = /\/rerank$/i.test(api.url) ? api.url : `${api.url}/rerank`;
            const headers = { 'Content-Type': 'application/json' };
            if (api.key) headers['Authorization'] = `Bearer ${api.key}`;
            const t0 = Date.now();
            const res = await D.fetch(endpoint, { method: 'POST', headers, body: JSON.stringify({ model: api.model, query: '测试', documents: ['测试文档'], top_n: 1 }) });
            if (!res.ok) { const t = await res.text().catch(() => res.statusText); throw new Error(`HTTP ${res.status}: ${t.slice(0, 200)}`); }
            return { ok: true, ms: Date.now() - t0, kind };
        }
        if (!api.model) throw new Error('未配置模型');
        const endpoint = /\/chat\/completions$/i.test(api.url) ? api.url : `${api.url}/chat/completions`;
        const headers = { 'Content-Type': 'application/json' };
        if (api.key) headers['Authorization'] = `Bearer ${api.key}`;
        const t0 = Date.now();
        const res = await D.fetch(endpoint, { method: 'POST', headers, body: JSON.stringify({ model: api.model, messages: [{ role: 'user', content: 'ping' }], max_tokens: 1 }) });
        if (!res.ok) { const t = await res.text().catch(() => res.statusText); throw new Error(`HTTP ${res.status}: ${t.slice(0, 200)}`); }
        return { ok: true, ms: Date.now() - t0, kind: 'chat' };
    }

