async function fetchModels(override) {
        const api = resolveApiFor(override);
        if (!api.url) throw new Error('未配置 API 地址');
        const endpoint = /\/models$/i.test(api.url) ? api.url : `${api.url}/models`;
        const headers = {};
        if (api.key) headers['Authorization'] = `Bearer ${api.key}`;
        const res = await D.fetch(endpoint, { method: 'GET', headers });
        if (!res.ok) { const t = await res.text().catch(() => res.statusText); throw new Error(`HTTP ${res.status}: ${t.slice(0, 200)}`); }
        const j = await res.json();
        const data = Array.isArray(j?.data) ? j.data : Array.isArray(j?.models) ? j.models : [];
        const models = data.map(m => String(m?.id || m?.model || m?.name || '').trim()).filter(Boolean);
        if (!models.length) throw new Error('未解析到模型列表');
        return models;
    }

